import{_ as e}from"./q-BD-hIznX.js";import{y as t,L as o}from"./q-DbZgC2Xw.js";const i={"about-us":{eyebrow:"About Us",title:"Rooted in natural wellness and everyday trust",description:"Moringa Store is built around clear product information, honest pricing, and a calm buying experience for people who want plant-based wellness essentials.",sections:[{heading:"What we stand for",body:"We focus on clean product presentation, practical routines, and a storefront that helps buyers make decisions with confidence instead of pressure."},{heading:"What customers can expect",body:"Reliable product pages, visible stock information, secure checkout, order tracking, and support that stays clear from purchase to delivery."}]},"wellness-journal":{eyebrow:"Wellness Journal",title:"Simple guidance for better daily routines",description:"Use moringa in ways that fit your schedule, from powders and teas to oils and wellness bundles. This page can grow into your real content hub over time.",sections:[{heading:"Content ideas to publish next",body:"How to choose between tea, powder, capsules, and oil. Best beginner products. Morning routines. Storage tips. Nutrition-focused blog posts and FAQ answers."},{heading:"Why this matters",body:"A real commerce brand earns trust through education, not just product listings. Search traffic, repeat visits, and higher conversion all benefit from a strong journal."}]},shipping:{eyebrow:"Shipping",title:"Delivery, dispatch, and order support",description:"Orders are processed after confirmation and moved through clear delivery stages so customers know what is happening after checkout.",sections:[{heading:"Dispatch window",body:"Most in-stock orders should be packed and handed to the courier within 1 to 2 business days unless otherwise stated during checkout."},{heading:"Delivery support",body:"Customers receive timeline updates for payment confirmation, shipping, out-for-delivery, and delivery completion inside the order history page."}]},returns:{eyebrow:"Returns",title:"Returns, cancellations, and issue resolution",description:"Return, refund, and replacement requests are accepted for 7 days after delivery. After that window closes, customers can still contact support for payment disputes where applicable.",sections:[{heading:"7-day return window",body:"Customers can request a return, refund, or replacement within 7 days from the delivered date shown in their order history."},{heading:"Support review",body:"Each request is reviewed by support. Items must match the store policy for damage, incorrect product, missing item, or approved replacement cases."}]},"privacy-policy":{eyebrow:"Privacy Policy",title:"How customer information is handled",description:"A hosted store needs a formal legal privacy policy, but this page already gives you a place to publish the data-handling commitments your customers expect.",sections:[{heading:"Data used by this store",body:"Account details, delivery addresses, order records, authentication data, and payment references needed to complete purchases and support customers."},{heading:"Before going live",body:"Replace this page with your lawyer-reviewed policy covering storage, third-party processors, analytics, cookies, data retention, and customer rights under the laws that apply to your audience."}]},terms:{eyebrow:"Terms",title:"Store terms and purchase conditions",description:"Professional storefronts should publish purchase terms, acceptable use, pricing disclaimers, fulfilment rules, and support boundaries in one place.",sections:[{heading:"What this page should cover",body:"Order acceptance, pricing accuracy, stock availability, fulfilment limitations, cancellation rules, returns, dispute handling, and website usage terms."},{heading:"Launch note",body:"Use this page as a placeholder now, but replace it with business-specific and legally reviewed terms before public hosting."}]},contact:{eyebrow:"Contact",title:"Get in touch with Moringa Store",description:"Customers should always know how to reach the business before and after placing an order.",sections:[{heading:"Customer support",body:"Email: moringastoreonline@gmail.com. Phone: +91 90332 27627. Location: Ahmedabad, Gujarat, India."},{heading:"Recommended support promise",body:"Reply to new customer enquiries within one business day and urgent order issues within a few working hours during business time."}]}},a=t(o(()=>e(()=>import("./q-CpPEaGn5.js"),[]),"s_ENnVG0kI0Bo"));export{a as I,i as P};
